'use strict';
const SEED=window.MILLER_SEED,KEY='miller-hq.workspace.v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const fmt=n=>Number(n).toLocaleString('en-US'),money=n=>Number(n).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}),dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'No date';
const safeURL=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
let storageOK=true,initialWarning='',state;
function fresh(){return {version:1,notes:[],tasks:[{id:'setup-1',title:'Review the June 2026 source snapshot',owner:'Research',status:'To do',priority:'High',due:'',details:'Starter setup task. Confirm source dates and budget stages before using figures.'},{id:'setup-2',title:'Set up the team calendar',owner:'Operations',status:'To do',priority:'Normal',due:'',details:'Starter setup task. Add confirmed meetings and event logistics.'},{id:'setup-3',title:'Add workspace owners and a backup routine',owner:'Operations',status:'To do',priority:'Normal',due:'',details:'Starter setup task. This first edition saves in one browser; export regular backups.'}],events:[],ledger:[],datasets:[],projectEdits:{},activity:[],settings:{workspace:'Miller HQ'}}}
try{const raw=localStorage.getItem(KEY);state=raw?validateBackup(JSON.parse(raw)):fresh()}catch(e){state=fresh();storageOK=false;initialWarning='Saved workspace could not be loaded. Your existing stored copy has not been overwritten. Export this session before closing.'}
let route='',filters={year:'2025',office:'',q:'',page:0},budgetMode='outlays',datasetIndex=0,datasetPage=0,datasetQuery='',noteQuery='',taskFilter='All',taskQuery='',importMode='data';
const nav=[['overview','◫','Overview'],['tasks','☑','Team workboard'],['calendar','▦','Calendar & events'],['notes','▤','Team notebook'],['city','⌖','City & neighborhoods'],['budget','▥','City budget'],['archive','▧','Election archive'],['ledger','＄','Expense ledger'],['library','▱','Source library'],['data','⇄','Data desk'],['brand','★','Brand room']];
$('#nav').innerHTML=nav.map(([id,icon,name],i)=>`${[4,8].includes(i)?'<div class="nav-divider"></div>':''}<a href="#${id}" data-route="${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</a>`).join('');
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4800)}
function save(message){if(!storageOK){toast('Changes are in memory only. Export a backup before closing.');$('#save-status').textContent='In memory only · export a backup';return}try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Saved locally · '+new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});if(message)toast(message)}catch{storageOK=false;$('#save-status').textContent='Storage full or unavailable · export a backup';toast('Browser storage is unavailable or full. Export a backup to keep your changes.')}}
function log(text){state.activity.unshift({id:uid(),text,time:new Date().toISOString()});state.activity=state.activity.slice(0,30)}
function heading(kicker,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function btn(label,action,cls='',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
function pill(t,cls=''){return `<span class="pill ${cls}">${esc(t)}</span>`}
function metric(label,value,caption){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-number">${value}</div><div class="metric-caption">${caption}</div></div>`}
function panel(title,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p class="panel-sub">${sub}</p>`:''}</div>${action}</div>${body}</section>`}
function empty(title,text,action=''){return `<div class="empty"><strong>${title}</strong>${text}${action?'<br>'+action:''}</div>`}
function projects(){return SEED.projects.map(p=>({...p,...state.projectEdits[p.id]}))}
function render(){route=location.hash.slice(1)||'overview';if(!nav.some(n=>n[0]===route))route='overview';$$('#nav a').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const pages={overview, tasks,calendar,notes,city,budget,archive,ledger,library,data:dataDesk,brand};$('#main').innerHTML=(!storageOK?`<div class="notice storage-warning">${esc(initialWarning||'Browser storage is unavailable. Export a backup before closing this session.')}</div>`:'')+pages[route]();document.title=nav.find(n=>n[0]===route)[2]+' · Miller HQ';if(route==='archive')renderResults();if(route==='data')renderDataset();}
function overview(){const open=state.tasks.filter(t=>t.status!=='Done'),done=state.tasks.filter(t=>t.status==='Done').length,upcoming=state.events.filter(e=>e.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return heading('COMMAND DESK / 01','The work starts here.','One workspace for the team, the city, and the work ahead.',pill('Local edition','blue')+btn('+ New note','new-note','primary'))+
`<div class="desk-strip"><span>Daily overview</span><span>2029 campaign cycle</span><span>Stamford, Connecticut</span></div><div class="metrics">${metric('Open team tasks',fmt(open.length),`${done} completed · editable setup workboard`)}${metric('Upcoming events',fmt(upcoming.length),'Confirmed events added by your team')}${metric('City operating budget','$726.4<small>M</small>','FY26/27 adopted · supplied June 2026 report')}${metric('Research archive','14,322','Historical result rows · 2019–2025')}</div>
<div class="dashboard-grid"><div>${panel('City fiscal snapshot',`<div class="panel-body"><div class="budget-comparison"><strong>$747.3M</strong><span>proposed operating receipts / FY26–27</span></div><div class="donut-layout"><div class="donut" role="img" aria-label="Property taxes 91.9 percent of proposed receipts"><div><strong>91.9%</strong><small>PROPERTY TAXES</small></div></div><div class="legend"><p><span>Property taxes</span><b>$686.5M</b></p><p><span>Departmental revenue</span><b>$28.5M</b></p><p><span>Intergovernmental aid</span><b>$22.5M</b></p><p><span>Other receipts</span><b>$9.8M</b></p></div></div><p class="chart-note">Historical snapshot from the supplied budget dossier. Proposed composition is separate from the adopted $726.4M operating total. Current figures require verification.</p></div>`,btn('Open fiscal desk ↗','go-budget','ghost'))}
${panel('Team priorities',open.slice(0,4).map(taskRow).join('')||empty('All caught up','No open tasks on the workboard.'),btn('Workboard ↗','go-tasks','ghost'))}
${panel('Public project register',`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Location</th><th>Review</th></tr></thead><tbody>${projects().slice(0,4).map(p=>`<tr><td><button class="inline-link" data-action="project" data-id="${esc(p.id)}">${esc(p.name)}</button></td><td>${esc(p.area)}</td><td>${pill(p.status,'blue')}</td></tr>`).join('')}</tbody></table></div>`,btn('City desk ↗','go-city','ghost'))}</div>
<div><section class="panel briefing"><div class="eyebrow">MILLER HQ / WORKING BRIEF</div><h2>Built for the work ahead.</h2><p>Keep public records close, decisions documented, and the team moving together. Your notes sit alongside the source material.</p>${btn('Open team notebook →','go-notes')}<div class="brief-bottom" style="margin-top:22px"><span>STAMFORD 2029</span><span>GROWING TOGETHER ↗</span></div></section>
${panel('Next on the calendar',upcoming.length?upcoming.slice(0,3).map(e=>`<div class="source-card"><div><h3>${esc(e.title)}</h3><p>${dateLabel(e.date)} · ${esc(e.time||'Time TBD')}<br>${esc(e.location||'Location TBD')}</p></div>${btn('View','edit-event','ghost',`data-id="${esc(e.id)}"`)}</div>`).join(''):empty('Make room for what’s next.','Add team meetings, public meetings, and event logistics.',btn('+ Add an event','new-event','primary')),btn('Calendar ↗','go-calendar','ghost'))}
${panel('Workspace pulse',`<div class="panel-body"><div class="mini-stat"><b>${state.notes.length.toString().padStart(2,'0')}</b><div>Team notes<small>Your annotations and working records</small></div></div><div class="mini-stat"><b>${state.datasets.length.toString().padStart(2,'0')}</b><div>Imported datasets<small>Excel, CSV, JSON, or a public JSON endpoint</small></div></div><div class="mini-stat"><b>07</b><div>Public projects<small>Imported names and approximate locations</small></div></div><div class="progress-track"><div style="width:${state.tasks.length?done/state.tasks.length*100:0}%"></div></div><small class="muted">${done} of ${state.tasks.length} team tasks completed</small></div>`)}
${panel('Recent activity',state.activity.length?state.activity.slice(0,4).map(a=>`<div class="source-card"><div><h3>${esc(a.text)}</h3><p>${new Date(a.time).toLocaleString()}</p></div></div>`).join(''):empty('A fresh start','Workspace changes will appear here.'))}</div></div>`}
function taskRow(t){return `<div class="task-item ${t.status==='Done'?'done':''}"><input type="checkbox" data-task-check="${esc(t.id)}" ${t.status==='Done'?'checked':''} aria-label="Mark ${esc(t.title)} ${t.status==='Done'?'open':'done'}"><div><strong>${esc(t.title)}</strong><small>${esc(t.owner||'Unassigned')} · ${t.due?dateLabel(t.due):'No due date'} ${t.priority==='High'?' · HIGH PRIORITY':''}</small></div>${btn('⋯','edit-task','ghost',`data-id="${esc(t.id)}" aria-label="Edit ${esc(t.title)}"`)}</div>`}
function tasks(){const rows=state.tasks.filter(t=>(taskFilter==='All'||t.status===taskFilter)&&[t.title,t.owner,t.details].join(' ').toLowerCase().includes(taskQuery.toLowerCase()));return heading('OPERATIONS / WORKBOARD','Keep the team moving.','Assign owners, record next steps, and track completion.',btn('+ Add task','new-task','primary'))+`<div class="notice">The initial three cards are setup tasks for this workspace. Replace or edit them as your team gets organized.</div>`+panel('Team workboard',`<div class="toolbar"><input aria-label="Search tasks" id="task-search" placeholder="Search tasks or owners…" value="${esc(taskQuery)}"><select id="task-filter" aria-label="Task status">${options(['All','To do','In progress','Done'],taskFilter)}</select></div><div id="task-list">${rows.map(taskRow).join('')||empty('No tasks in this view','Change the filter or add a task.')}</div><div class="pager"><span id="task-count">${rows.length} tasks in this view</span><span>${state.tasks.filter(t=>t.status==='Done').length} completed</span></div>`)}
function calendar(){const rows=[...state.events].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return heading('OPERATIONS / CALENDAR','A shared sense of what’s next.','Meetings, public events, and the details that make them run.',btn('Export calendar','export-calendar')+btn('+ Add event','new-event','primary'))+(rows.length?`<div class="calendar-list">${rows.map(e=>{const dt=new Date(e.date+'T12:00:00');return `<article class="event-card"><div class="date-tile"><span>${dt.toLocaleDateString('en-US',{month:'short'}).toUpperCase()} ${dt.getFullYear()}</span><b>${dt.getDate()}</b></div><div class="event-detail"><h3>${esc(e.title)}</h3><p>${esc(e.time||'Time TBD')} · ${esc(e.location||'Location TBD')} · ${esc(e.owner||'Unassigned')}</p><p>${esc(e.notes||'')}</p></div>${pill(e.date<today()?'Past':e.kind,'blue')}${btn('Edit','edit-event','',`data-id="${esc(e.id)}"`)}</article>`}).join('')}</div>`:panel('Team calendar',empty('Your calendar is ready.','Add the first confirmed event. Dates from the old HQ have not been treated as current commitments.',btn('+ Add event','new-event','primary'))))}
function notes(){return heading('TEAM KNOWLEDGE / NOTEBOOK','Keep the context.','Record decisions, attach source links, and keep working notes by topic.',btn('+ New note','new-note','primary'))+`<div class="panel"><div class="toolbar"><input id="note-search" aria-label="Search notes" placeholder="Search titles, topics, or note text…" value="${esc(noteQuery)}"><span class="muted">${state.notes.length} notes</span></div></div><div id="note-grid" class="note-grid">${noteCards()}</div>`}
function noteCards(){const rows=state.notes.filter(n=>[n.title,n.body,n.topic].join(' ').toLowerCase().includes(noteQuery.toLowerCase()));return rows.length?rows.map(n=>`<article class="note-card"><div class="note-meta">${esc(n.topic)} · ${dateLabel(n.updated.slice(0,10))}</div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.source?link(n.source,'Source reference'):''}<div class="note-footer"><small class="muted">${esc(n.owner||'Team note')}</small>${btn('Edit note','edit-note','',`data-id="${esc(n.id)}"`)}</div></article>`).join(''):empty('Room for your thinking.','Add a note or adjust your search.',btn('+ New note','new-note','primary'))}
function city(){return heading('PUBLIC INFORMATION / CITY DESK','Stamford, on the ground.','A location index for public projects, service issues, and team annotations.',btn('+ City note','new-city-note','primary'))+`<div class="map-layout"><div class="map-panel"><div class="map-label">STAMFORD / PUBLIC PROJECT INDEX</div>${mapSVG()}<div class="map-caption">Illustrative location diagram · markers use supplied approximate coordinates.<br>Not a street map, surveyed boundary, or electoral district map.</div></div>${panel('Public project register',projects().map((p,i)=>`<div class="project-item" role="button" tabindex="0" data-action="project" data-id="${esc(p.id)}"><span class="project-number">${i+1}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.area)}</p>${pill(p.status,'blue')}</div></div>`).join(''))}</div><div style="margin-top:20px">${panel('City desk notes',`<div class="panel-body">${state.notes.filter(n=>n.topic==='City & neighborhoods'||n.topic==='Public projects').length?state.notes.filter(n=>n.topic==='City & neighborhoods'||n.topic==='Public projects').map(n=>`<div class="source-card"><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div>${btn('Edit','edit-note','ghost',`data-id="${esc(n.id)}"`)}</div>`).join(''):empty('Add local context','Capture meeting logistics, project updates, public service observations, or source references.')}</div>`)}</div>`}
function mapSVG(){return `<svg viewBox="0 0 620 540" role="img" aria-label="Illustrative Stamford project location diagram"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d8dfd8" stroke-width=".7"/></pattern></defs><rect width="620" height="540" fill="url(#grid)"/><path d="M0 443Q140 424 240 460T620 452V540H0" fill="#cbdbdf"/><path d="M130 450L96 354 140 255 119 96 208 70 325 87 450 56 478 191 450 300 491 399 449 456 388 435 320 473 252 450 207 474Z" fill="#f5f5eb" stroke="#b5c2b6" stroke-width="1.5"/><path d="M124 253Q250 195 464 225M111 379Q300 414 477 388" stroke="#d9c8a3" stroke-width="9" fill="none"/><path d="M124 253Q250 195 464 225M111 379Q300 414 477 388" stroke="#fffaf0" stroke-width="5" fill="none"/><path d="M215 83Q220 240 281 451M387 77Q340 240 366 443M150 324L457 317M165 157L444 153" stroke="#d2d8cc" stroke-width="3" fill="none"/><path d="M293 84Q270 238 314 329T297 466" stroke="#b8d0d1" stroke-width="4" fill="none"/><text x="255" y="125">NORTH STAMFORD</text><text x="149" y="246">MERRITT PKWY</text><text x="361" y="307">GLENBROOK</text><text x="156" y="363">WEST SIDE</text><text x="333" y="372">DOWNTOWN</text><text x="235" y="419">SOUTH END</text><text x="230" y="509" style="letter-spacing:3px;fill:#718d97">LONG ISLAND SOUND</text><text x="550" y="84">N ↑</text>${projects().map((p,i)=>{const baseX=160+(p.lng+73.58)*3800,baseY=440-(p.lat-41.035)*2700;const offsets=[[-29,13],[8,13],[30,-9],[-18,-24],[0,0],[0,0],[15,0]];const [dx,dy]=offsets[i]||[0,0],x=baseX+dx,y=baseY+dy;return `<g class="map-pin" role="button" tabindex="0" data-action="project" data-id="${esc(p.id)}" aria-label="${esc(p.name)}" transform="translate(${x},${y})"><title>${esc(p.name)}</title><line x1="0" y1="0" x2="${-dx}" y2="${-dy}"/><circle r="13"/><text y="3">${i+1}</text></g>`}).join('')}</svg>`}
function budget(){const b=SEED.budget,rows=b[budgetMode];return heading('PUBLIC FINANCE / FISCAL DESK','Follow the city’s dollars.','FY2026–2027 · figures transcribed from the supplied June 20, 2026 budget dossier.',btn('Export table','export-budget')+btn('+ Budget note','new-budget-note','primary'))+`<div class="notice">Reference snapshot, not a live fiscal feed. Proposed line items and adopted totals represent different stages. These figures have not been independently reverified against current city records.</div><div class="metrics">${metric('Adopted operating','$726.4<small>M</small>','Final operating total reported in dossier')}${metric('Adopted education','$360.0<small>M</small>','Board of Education · reported final')}${metric('Approved capital','$60.6<small>M</small>','Separate from operating spending')}${metric('Reported tax increase','4.8<small>%</small>','Dossier’s final tax-impact figure')}</div><div class="split"><div>${panel('Proposed operating composition',`<div class="panel-body"><div class="budget-tabs">${btn('Outlays','budget-outlays',budgetMode==='outlays'?'active':'')}${btn('Receipts','budget-receipts',budgetMode==='receipts'?'active':'')}</div>${rows.map(([n,v])=>`<div class="bar-row"><span>${esc(n)}</span><div class="bar-track"><div class="bar-fill" style="width:${v/747.3*100}%"></div></div><b>$${v.toFixed(1)}M</b></div>`).join('')}<p class="chart-note">Mayor-proposed category mix: $747.3M total. Amounts are rounded. This chart does not depict final adopted category allocations.</p></div>`)}</div><div>${panel('Proposal → adoption',`<div class="inventory"><div class="inventory-row"><div>Proposal headline<small>Rounded opening request in the source</small></div><strong>$747.4M</strong></div><div class="inventory-row"><div>Reported final operating<small>After board actions</small></div><strong>$726.4M</strong></div><div class="inventory-row"><div>Reported reduction<small>Difference between stages, not a deficit</small></div><strong>−$21.0M</strong></div><div class="inventory-row"><div>Capital proposal / approved<small>Separate capital authorization</small></div><strong>$73.2M / $60.6M</strong></div></div>`)}${panel('Source trail',`<div class="panel-body"><p class="muted">Imported from <strong>Stamford_CT_Budget.html</strong> and its fiscal monitor companion. Review original public documents before treating the snapshot as current.</p><p>${link('https://www.stamfordct.gov/government/administration/budget','City budget source')}</p><p>${link('https://www.stamfordadvocate.com/news/article/stamford-ct-approved-city-boe-budget-22247547.php','Adopted budget reporting cited in dossier')}</p></div>`)}</div></div>`+panel('Proposed '+budgetMode+' detail',`<div class="table-wrap"><table><thead><tr><th>Category</th><th class="num">Amount / millions</th><th class="num">Share / calculated</th><th>Budget stage</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td class="num">$${v.toFixed(1)}M</td><td class="num">${(v/747.3*100).toFixed(1)}%</td><td>${pill('Proposed','blue')}</td></tr>`).join('')}</tbody></table></div>`)}
function options(items,value){return items.map(i=>`<option value="${esc(i)}" ${String(i)===String(value)?'selected':''}>${esc(i||'All offices')}</option>`).join('')}
function archive(){return heading('PUBLIC RECORDS / ELECTION ARCHIVE','The record, in detail.','Searchable historical source rows · 2019–2025 · imported June 25, 2026.',btn('Export filtered rows','export-results'))+`<div class="notice">These are aggregate historical result records, not individual voter records. Rows may include separate ballot lines and reporting districts; this view does not infer citywide totals or compare different district systems.</div>`+panel('Historical results',`<div class="toolbar"><input id="result-search" aria-label="Search election records" placeholder="Candidate, office, district, party…" value="${esc(filters.q)}"><select id="result-year" aria-label="Election year">${options(['All years',...new Set(SEED.results.map(r=>String(r.year)))].sort((a,b)=>b.localeCompare(a)),filters.year)}</select><select id="result-office" aria-label="Office">${options(['',...new Set(SEED.results.filter(r=>filters.year==='All years'||String(r.year)===filters.year).map(r=>r.office))].sort(),filters.office)}</select></div><div class="table-wrap"><table><thead><tr><th>Year</th><th>Candidate / ballot line</th><th>Office</th><th>Reporting district</th><th class="num">Votes</th><th>Source</th></tr></thead><tbody id="result-rows"></tbody></table></div><div id="result-pager" class="pager"></div>`)}
function resultRows(){const q=filters.q.toLowerCase();return SEED.results.filter(r=>(filters.year==='All years'||String(r.year)===filters.year)&&(!filters.office||r.office===filters.office)&&(!q||[r.candidate,r.office,r.district,r.party].join(' ').toLowerCase().includes(q)))}
function renderResults(){const rows=resultRows(),max=Math.max(0,Math.ceil(rows.length/40)-1);filters.page=Math.min(max,filters.page);$('#result-rows').innerHTML=rows.slice(filters.page*40,filters.page*40+40).map(r=>`<tr><td>${r.year}</td><td class="row-title">${esc(r.candidate)}<small>Party / ballot line: ${esc(r.party||'—')}</small></td><td>${esc(r.office)}</td><td>${esc(r.district)}</td><td class="num">${fmt(r.votes)}</td><td>${link(r.sourceUrl,'View')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No records match these filters.</td></tr>';$('#result-pager').innerHTML=`<span>${fmt(rows.length)} matching rows · page ${filters.page+1} of ${max+1}</span><div class="actions">${btn('← Previous','results-prev','',filters.page===0?'disabled':'')}${btn('Next →','results-next','',filters.page===max?'disabled':'')}</div>`}
function ledger(){const total=state.ledger.reduce((n,r)=>n+Number(r.amount),0),paid=state.ledger.filter(r=>r.status==='Paid').reduce((n,r)=>n+Number(r.amount),0);return heading('OPERATIONS / EXPENSE LEDGER','Know what’s committed.','A simple internal expense register. Add actual amounts and receipt references.',btn('Export expenses','export-ledger')+btn('+ Add expense','new-expense','primary'))+`<div class="metrics">${metric('Recorded expenses',money(total),'All expense records')}${metric('Paid',money(paid),'Marked as paid by your team')}${metric('Unpaid',money(total-paid),'Planned or approved expenses')}${metric('Entries',state.ledger.length,'Records in this browser')}</div>`+panel('Expense register',state.ledger.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Description / vendor</th><th>Category</th><th class="num">Amount</th><th>Status</th><th></th></tr></thead><tbody>${state.ledger.map(r=>`<tr><td>${dateLabel(r.date)}</td><td class="row-title">${esc(r.title)}<small>${esc(r.vendor||'—')}</small></td><td>${esc(r.category)}</td><td class="num">${money(r.amount)}</td><td>${pill(r.status,r.status==='Paid'?'green':'blue')}</td><td>${btn('Edit','edit-expense','small-button',`data-id="${esc(r.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Start with a real expense.','No campaign spending or fundraising totals have been invented.',btn('+ Add expense','new-expense','primary')))+`<p class="chart-note">Internal operations ledger only. Filing, payment processing, contribution limits, and compliance calculations are not implemented.</p>`}
function library(){const sources=SEED.sources.filter((s,i,a)=>a.findIndex(x=>x.url===s.url)===i);return heading('RESEARCH / SOURCE LIBRARY','A clear trail back to the source.','Keep source records separate from team annotations and later updates.',btn('+ Source note','new-source-note','primary'))+`<div class="split"><div>${panel('Public source directory',sources.map(s=>`<div class="source-card"><div><h3>${esc(s.name)}</h3><p>${esc(s.kind)}<br>Packet snapshot: ${esc(s.updated)}</p></div>${link(s.url,'Open source')}</div>`).join(''))}</div><div>${panel('Imported material',`<div class="inventory"><div class="inventory-row"><div>Chilton terminal<small>Reference for desk navigation, tabular analysis, imports and reports</small></div>${pill('Design reference','blue')}</div><div class="inventory-row"><div>Budget dossier + fiscal monitor<small>Selected neutral fiscal figures; proposed and adopted kept separate</small></div>${pill('Integrated','green')}</div><div class="inventory-row"><div>HQ seed data + cached results<small>14,322 historical result rows and seven public project locations</small></div>${pill('Integrated','green')}</div><div class="inventory-row"><div>Merch reference<small>Navy, cream, orange and gold; Miller 2029 identity</small></div>${pill('Integrated','green')}</div><div class="inventory-row"><div>Opposition / incumbent / battleground reports<small>Targeting, attack plans and tailored persuasion material are not included in this edition</small></div>${pill('Not imported')}</div><div class="inventory-row"><div>Email ZIP and README<small>Packaging and provenance references</small></div>${pill('Reference','blue')}</div></div>`)}${panel('Research workflow',`<div class="panel-body"><p>Open the original public source, check its date and scope, then add a note with a direct link. Keep observations and confirmed facts distinguishable.</p><p>Use the Data desk to import updated tables or pull a public JSON feed. Imports remain separate from the archived baseline.</p>${btn('Open data desk →','go-data','primary')}</div>`)}</div></div>`}
function dataDesk(){return heading('DATA / IMPORT & EXPORT','Bring your working data together.','Import tables, pull a public JSON feed, and back up the whole workspace.',btn('Export backup','backup')+btn('Restore backup','restore')+btn('+ Import data','import','primary'))+`<div class="notice">Browser-only edition: saves on this device, with no team sync yet. Public JSON feeds must allow browser access (CORS). Login, shared storage, scheduled refresh, and hosting are deferred to the next phase.</div><div class="split">${panel('Connect a public JSON feed',`<form id="feed-form" class="panel-body"><label for="feed-url">Public HTTPS endpoint</label><input id="feed-url" type="url" required placeholder="https://example.gov/data.json" style="width:100%;margin:10px 0"><div class="actions"><button class="primary" type="submit" id="feed-button">Fetch & preview →</button><span class="muted" style="font-size:10px">JSON array or { data: [...] }</span></div><p class="chart-note">No credentials or API secrets are sent. Imported data is saved only after you review the preview.</p></form>`)}${panel('Import a file',`<div class="panel-body"><h3>Excel, CSV, and JSON tables</h3><p class="muted">Excel files up to 15 MB; CSV/JSON up to 5 MB. Up to 20,000 rows and 50 columns per sheet. Select a sheet and preview before importing. Each import keeps its filename, date, and optional source.</p>${btn('Choose a file →','import','primary')}${btn('Download CSV template','template','ghost')}</div>`)}</div>`+panel('Your imported datasets',`<div class="toolbar"><select id="dataset-select" aria-label="Select dataset">${state.datasets.map((d,i)=>`<option value="${i}" ${i===datasetIndex?'selected':''}>${esc(d.name)} (${d.rows.length})</option>`).join('')||'<option>No datasets imported</option>'}</select><input id="dataset-search" aria-label="Search imported data" placeholder="Search this dataset…" value="${esc(datasetQuery)}">${btn('Export Excel','excel-dataset','',!state.datasets.length?'disabled':'')+btn('Export CSV','export-dataset','',!state.datasets.length?'disabled':'')}${btn('Remove','delete-dataset','',!state.datasets.length?'disabled':'')}</div><div id="dataset-content"></div>`)}
function renderDataset(){if(!$('#dataset-content'))return;datasetIndex=Math.min(datasetIndex,Math.max(0,state.datasets.length-1));const d=state.datasets[datasetIndex];if(!d){$('#dataset-content').innerHTML=empty('Your data belongs here.','Import a table to search, annotate in the notebook, and export.');return}const rows=d.rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(datasetQuery.toLowerCase())),max=Math.max(0,Math.ceil(rows.length/30)-1);datasetPage=Math.min(max,datasetPage);$('#dataset-content').innerHTML=`<div class="panel-body" style="padding-bottom:10px"><span class="muted">Imported ${dateLabel(d.imported.slice(0,10))} · ${esc(d.name)}</span>${d.source?' · '+link(d.source,'Source'):''}</div><div class="table-wrap"><table><thead><tr>${d.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(datasetPage*30,datasetPage*30+30).map(r=>`<tr>${d.columns.map(c=>`<td>${esc(r[c])}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${d.columns.length}" class="empty">No matching rows.</td></tr>`}</tbody></table></div><div class="pager"><span>${fmt(rows.length)} rows · page ${datasetPage+1} of ${max+1}</span><div class="actions">${btn('← Previous','dataset-prev','',!datasetPage?'disabled':'')}${btn('Next →','dataset-next','',datasetPage===max?'disabled':'')}</div></div>`}
function brand(){return heading('IDENTITY / BRAND ROOM','Miller. Stamford. 2029.','The supplied merch direction, carried into the team workspace.',btn('Download wordmark SVG','download-brand','primary'))+`<div class="brand-stage"><div class="candidate">MILLER <span>2029</span></div><div class="slogan">Growing the city that works, together</div></div><div class="swatches">${[['Navy','#0C2139'],['Cream','#F3E7CF'],['Orange','#E55427'],['Gold','#E7AA34'],['Paper','#F5F5F0']].map(([n,c])=>`<div class="swatch"><div style="background:${c}"></div><strong>${n}</strong><small>${c}</small></div>`).join('')}</div><div class="split">${panel('Campaign identity',`<div class="panel-body"><h3>MILLER 2029</h3><p>Growing the city that works, together</p><p class="muted">Bold condensed lettering, a warm cream foundation, deep navy, and orange with gold accents follow the supplied merchandise image.</p><p class="chart-note">The downloadable SVG contains editable text. Typography may vary if Barlow Condensed is unavailable on another computer.</p></div>`)}${panel('Merch & production notes',`<div class="panel-body"><p>Keep sizing, vendor quotes, print proofs, and inventory notes in the team notebook. Record purchases in the expense ledger.</p>${btn('+ Add production note','new-brand-note','primary')}</div>`)}</div>`}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${btn('×','close','', 'aria-label="Close dialog"')}</div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal input:not([type=hidden]),#modal textarea')?.focus(),20)}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function selectField(label,name,items,value){return `<label>${label}<select name="${name}">${options(items,value)}</select></label>`}
function textField(label,name,value=''){return `<label class="full">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function formEnd(type,id){return `</div><div class="form-actions">${id?btn('Delete','delete-record','danger',`data-type="${type}" data-id="${esc(id)}"`):''}${btn('Cancel','close')}<button type="submit" class="primary">Save ${type==='ledger'?'expense':type.replace(/s$/,'')}</button></div></form>`}
function editor(type,id,topic){const row=state[type].find(r=>r.id===id)||{};let body=`<form id="record-form" data-type="${type}" data-id="${esc(id||'')}"><div class="form-grid">`;
if(type==='notes')body+=field('Title','title',row.title,'text','required maxlength="180"')+field('Owner','owner',row.owner,'text','maxlength="100"')+selectField('Topic','topic',['General','City & neighborhoods','Public projects','City budget','Sources','Operations','Merch & production'],row.topic||topic||'General')+field('Source URL (optional)','source',row.source,'url','placeholder="https://…"')+textField('Note','body',row.body);
if(type==='tasks')body+=field('Task','title',row.title,'text','required maxlength="180"')+field('Owner','owner',row.owner,'text','maxlength="100"')+selectField('Status','status',['To do','In progress','Done'],row.status||'To do')+selectField('Priority','priority',['Normal','High'],row.priority||'Normal')+field('Due date','due',row.due,'date')+textField('Details / next step','details',row.details);
if(type==='events')body+=field('Event title','title',row.title,'text','required maxlength="180"')+selectField('Type','kind',['Team meeting','Public meeting','Event','Deadline'],row.kind||'Team meeting')+field('Date','date',row.date||today(),'date','required')+field('Time (New York)','time',row.time,'time')+field('Location','location',row.location,'text','maxlength="200"')+field('Owner','owner',row.owner,'text','maxlength="100"')+textField('Logistics / notes','notes',row.notes);
if(type==='ledger')body+=field('Description','title',row.title,'text','required maxlength="180"')+field('Vendor','vendor',row.vendor,'text','maxlength="180"')+field('Amount (USD)','amount',row.amount??'','number','required min="0.01" max="100000000" step="0.01"')+field('Date','date',row.date||today(),'date','required')+selectField('Category','category',['Office','Events','Merchandise','Travel','Software','Professional services','Other'],row.category||'Other')+selectField('Status','status',['Planned','Approved','Paid'],row.status||'Planned')+field('Receipt URL (optional)','receipt',row.receipt,'url')+textField('Notes','notes',row.notes);
modal(`${id?'Edit':'New'} ${type==='ledger'?'expense':type.replace(/s$/,'')}`,body+formEnd(type,id));}
function projectDetail(id){const p=projects().find(p=>p.id===id);if(!p)return;modal(p.name,`<form id="project-form" data-id="${esc(id)}"><div class="detail-grid"><div><small>LOCATION</small><p>${esc(p.area)}</p></div><div><small>BASELINE</small><p>June 2026 supplied packet</p></div></div><div class="form-grid">${selectField('Review status','status',['Needs verification','Under review','Verified by team','Monitoring'],p.status)}${field('Owner','owner',p.owner||'')}${field('Source URL','source',p.source||'','url')}${field('Last verified','verified',p.verified||'','date')}${textField('Team annotation','notes',p.notes)}</div><p class="chart-note">This annotation overlays the archived project record. A status is a team assertion, not an independent verification.</p><div class="form-actions">${btn('Cancel','close')}<button class="primary" type="submit">Save annotation</button></div></form>`)}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows,cols){cols=cols||Object.keys(rows[0]||{});const q=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';return '\uFEFF'+[cols.map(q).join(','),...rows.map(r=>cols.map(c=>q(r[c])).join(','))].join('\r\n')}
function exportBackup(){download('Miller-HQ-backup-'+today()+'.json',JSON.stringify({...state,exported:new Date().toISOString()},null,2));toast('Workspace backup downloaded. Includes your notes and imported tables.');}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted)quoted=false;else if(cell==='')quoted=true;else throw Error('Invalid quote in CSV field.')}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c;}if(quoted)throw Error('Unclosed quoted field in CSV.');row.push(cell);if(row.some(x=>x!==''))rows.push(row);if(rows.length<2)throw Error('The CSV needs a header and at least one data row.');const cols=rows.shift().map(x=>x.trim());if(cols.some(c=>!c)||new Set(cols).size!==cols.length)throw Error('CSV column names must be unique and nonempty.');if(rows.some(r=>r.length!==cols.length))throw Error('Every CSV row must match the number of header columns.');return rows.map(r=>Object.fromEntries(cols.map((c,i)=>[c,r[i]])))}
function normalizeRows(data){const rows=Array.isArray(data)?data:Array.isArray(data?.data)?data.data:Array.isArray(data?.records)?data.records:null;if(!rows||!rows.length)throw Error('Expected a nonempty JSON array of objects, or { data: [...] }.');if(rows.length>20000)throw Error('Limit each dataset to 20,000 rows.');if(rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('Each row must be an object with named fields.');const columns=[...new Set(rows.flatMap(r=>Object.keys(r)))];if(!columns.length||columns.length>50)throw Error('A dataset must have 1–50 columns.');if(columns.some(c=>c.length>180||['__proto__','constructor','prototype'].includes(c)))throw Error('Invalid column name.');const clean=rows.map(r=>Object.fromEntries(columns.map(k=>{const v=r[k];const val=v===null||v===undefined?'':typeof v==='object'?JSON.stringify(v):v;if(String(val).length>10000)throw Error('A cell exceeds 10,000 characters.');return [k,val]})));return {columns,rows:clean}}
let pendingDataset;
function previewImport(rows,name,source=''){const normalized=normalizeRows(rows);pendingDataset={id:uid(),name,source,imported:new Date().toISOString(),...normalized};modal('Review your data import',`<p><strong>${esc(name)}</strong> · ${fmt(normalized.rows.length)} rows · ${normalized.columns.length} columns</p><div class="data-preview">${esc(JSON.stringify(normalized.rows.slice(0,3),null,2))}</div><p class="chart-note">The first three rows are shown. Review the destination before confirming. Archived baseline records remain unchanged.</p><div class="form-actions">${btn('Cancel','close')}${btn('Confirm import','confirm-import','primary')}</div>`)}
function validateBackup(v){if(!v||v.version!==1)throw Error('Not a Miller HQ version 1 backup.');const clean=fresh();const allowed={notes:['id','title','owner','topic','source','body','updated'],tasks:['id','title','owner','status','priority','due','details','updated'],events:['id','title','kind','date','time','location','owner','notes','updated'],ledger:['id','title','vendor','amount','date','category','status','receipt','notes','updated']};for(const [k,fields] of Object.entries(allowed)){if(!Array.isArray(v[k])||v[k].length>5000)throw Error('Invalid '+k+' list.');const ids=new Set();clean[k]=v[k].map(r=>{if(!r||typeof r!=='object'||!r.id||ids.has(r.id)||typeof r.title!=='string')throw Error('Invalid or duplicate record in '+k);ids.add(r.id);const n=Object.fromEntries(fields.map(f=>[f,String(r[f]??'')]));if(Object.values(n).some(s=>s.length>50000))throw Error('Record text is too long.');if(k==='ledger'&&(!Number.isFinite(Number(n.amount))||Number(n.amount)<=0))throw Error('Invalid expense amount.');if(k==='tasks'&&!['To do','In progress','Done'].includes(n.status))throw Error('Invalid task status.');if(['events','ledger'].includes(k)&&(!/^\d{4}-\d{2}-\d{2}$/.test(n.date)||Number.isNaN(Date.parse(n.date))))throw Error('Invalid record date.');if(k==='notes'&&!n.updated)n.updated=new Date().toISOString();return n})}if(!Array.isArray(v.datasets)||v.datasets.length>30)throw Error('Invalid dataset list.');clean.datasets=v.datasets.map(d=>({id:String(d.id||uid()),name:String(d.name||'Imported dataset'),source:safeURL(d.source),imported:String(d.imported||new Date().toISOString()),...normalizeRows(d.rows)}));clean.projectEdits={};for(const p of SEED.projects){const r=v.projectEdits?.[p.id];if(r)clean.projectEdits[p.id]=Object.fromEntries(['status','owner','source','verified','notes'].map(k=>[k,String(r[k]??'')]))}clean.activity=Array.isArray(v.activity)?v.activity.slice(0,30).filter(a=>a&&typeof a.text==='string'&&!Number.isNaN(Date.parse(a.time))).map(a=>({id:String(a.id),text:a.text,time:a.time})):[];return clean}
let pendingBackup;
function searchDialog(){modal('Search Miller HQ',`<input id="global-search" placeholder="Search pages, notes, tasks, projects…" aria-label="Search workspace" style="width:100%"><div id="global-results" class="search-results"></div>`);searchResults('')}
function searchResults(q){q=q.toLowerCase();const all=[...nav.map(([id,,name])=>({title:name,kind:'Workspace',action:'navigate',id})),...state.notes.map(r=>({title:r.title,kind:'Note · '+r.topic,action:'edit-note',id:r.id,body:r.body})),...state.tasks.map(r=>({title:r.title,kind:'Task · '+r.owner,action:'edit-task',id:r.id})),...projects().map(r=>({title:r.name,kind:'Public project · '+r.area,action:'project',id:r.id}))];$('#global-results').innerHTML=all.filter(r=>(r.title+' '+r.kind+' '+(r.body||'')).toLowerCase().includes(q)).slice(0,25).map(r=>`<button class="search-result" data-action="${r.action}" data-id="${esc(r.id)}">${esc(r.title)}<small>${esc(r.kind)}</small></button>`).join('')||empty('No matches','Try a different phrase.');}
function settings(){modal('About this workspace',`<p><strong>Miller HQ · first edition</strong></p><p>The terminal opens directly. Notes, tasks, events, expenses, project annotations, and imported datasets save in this browser’s local storage.</p><p>Export a backup before switching computers or clearing browser data. Another team member can restore that backup, replacing their local workspace after confirmation.</p><div class="notice">Login, user roles, shared storage, automatic updates, and live hosting are not active in this edition.</div><p class="muted">Archived seed: June 25, 2026. The app works offline after download; online fonts and external sources need a connection.</p><div class="form-actions">${btn('Export backup','backup','primary')}${btn('Close','close')}</div>`)}
const actions={
'new-note':()=>editor('notes'),'new-city-note':()=>editor('notes',null,'City & neighborhoods'),'new-budget-note':()=>editor('notes',null,'City budget'),'new-source-note':()=>editor('notes',null,'Sources'),'new-brand-note':()=>editor('notes',null,'Merch & production'),'edit-note':el=>editor('notes',el.dataset.id),'new-task':()=>editor('tasks'),'edit-task':el=>editor('tasks',el.dataset.id),'new-event':()=>editor('events'),'edit-event':el=>editor('events',el.dataset.id),'new-expense':()=>editor('ledger'),'edit-expense':el=>editor('ledger',el.dataset.id),'project':el=>projectDetail(el.dataset.id),'close':()=>$('#modal').close(),'backup':exportBackup,'settings':settings,'print':()=>window.print(),'search':searchDialog,'navigate':el=>{$('#modal').close();location.hash=el.dataset.id},
'budget-outlays':()=>{budgetMode='outlays';render()},'budget-receipts':()=>{budgetMode='receipts';render()},'results-prev':()=>{filters.page--;renderResults()},'results-next':()=>{filters.page++;renderResults()},'dataset-prev':()=>{datasetPage--;renderDataset()},'dataset-next':()=>{datasetPage++;renderDataset()},
'export-results':()=>{const r=resultRows();download('Miller-HQ-election-archive.csv',csv(r,['year','candidate','party','office','district','votes','sourceUrl']),'text/csv');toast(r.length+' rows exported.')},
'export-budget':()=>download('Miller-HQ-proposed-'+budgetMode+'.csv',csv(SEED.budget[budgetMode].map(([category,amount])=>({category,amount_millions:amount,stage:'Mayor proposed FY2026-2027',source:'Supplied Stamford_CT_Budget.html, June 20 2026'}))),'text/csv'),
'export-ledger':()=>download('Miller-HQ-expenses.csv',csv(state.ledger,['date','title','vendor','category','amount','status','receipt','notes']),'text/csv'),
'export-dataset':()=>{const d=state.datasets[datasetIndex];if(d)download('Miller-HQ-dataset.csv',csv(d.rows,d.columns),'text/csv')},
'import':()=>{importMode='data';$('#import-file').accept='.json,.csv';$('#import-file').click()},'restore':()=>{importMode='backup';$('#import-file').accept='.json';$('#import-file').click()},
'confirm-import':()=>{if(!pendingDataset)return;if(state.datasets.length>=30){toast('Maximum 30 datasets per workspace.');return}state.datasets.push(pendingDataset);datasetIndex=state.datasets.length-1;log('Imported '+pendingDataset.name);pendingDataset=null;save('Dataset imported.');$('#modal').close();location.hash='data';render()},
'confirm-restore':()=>{if(!pendingBackup)return;state=pendingBackup;pendingBackup=null;storageOK=true;initialWarning='';log('Restored workspace backup');save('Workspace restored.');$('#modal').close();render()},
'delete-record':el=>{const {type,id}=el.dataset;modal('Delete this record?',`<p>This removes the record from this local workspace. Export a backup first if you need to keep a copy.</p><div class="form-actions">${btn('Cancel','close')}${btn('Delete record','confirm-delete','accent',`data-type="${type}" data-id="${esc(id)}"`)}</div>`)},
'confirm-delete':el=>{const {type,id}=el.dataset;if(!['notes','tasks','events','ledger'].includes(type))return;state[type]=state[type].filter(r=>r.id!==id);log('Deleted a '+type.replace(/s$/,''));save('Record deleted.');$('#modal').close();render()},
'delete-dataset':()=>{const d=state.datasets[datasetIndex];if(!d)return;modal('Remove this dataset?',`<p>Remove <strong>${esc(d.name)}</strong> and its ${d.rows.length} rows from this browser?</p><div class="form-actions">${btn('Cancel','close')}${btn('Remove dataset','confirm-delete-dataset','accent',`data-id="${esc(d.id)}"`)}</div>`)},
'confirm-delete-dataset':el=>{state.datasets=state.datasets.filter(d=>d.id!==el.dataset.id);datasetIndex=0;log('Removed an imported dataset');save('Dataset removed.');$('#modal').close();render()},
'template':()=>download('Miller-HQ-data-template.csv','title,category,status,source,notes\r\nPublic project review,City information,Needs verification,https://www.stamfordct.gov/,Add a source and review date\r\n','text/csv'),
'export-calendar':()=>{const c=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const events=state.events.map(e=>{const stamp=e.date.replace(/-/g,'');return ['BEGIN:VEVENT','UID:'+e.id+'@millerhq.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z',e.time?'DTSTART;TZID=America/New_York:'+stamp+'T'+e.time.replace(':','')+'00':'DTSTART;VALUE=DATE:'+stamp,'SUMMARY:'+c(e.title),'LOCATION:'+c(e.location),'DESCRIPTION:'+c(e.notes),'END:VEVENT'].join('\r\n')});download('Miller-HQ-calendar.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Miller HQ//Team Calendar//EN','CALSCALE:GREGORIAN',...events,'END:VCALENDAR'].join('\r\n'),'text/calendar');toast('Calendar file downloaded.')},
'download-brand':()=>download('Miller-2029-wordmark.svg','<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="500" viewBox="0 0 1400 500"><rect width="1400" height="500" fill="#0c2139"/><text x="700" y="250" text-anchor="middle" fill="#f3e7cf" font-family="Barlow Condensed, Impact, Arial Narrow, sans-serif" font-style="italic" font-weight="800" font-size="180">MILLER <tspan fill="#e7aa34">2029</tspan></text><path d="M140 310H1270L1250 391H120Z" fill="#e55427"/><text x="700" y="364" text-anchor="middle" fill="#fff6e6" font-family="Barlow Condensed, Arial, sans-serif" font-weight="700" font-size="42">Growing the city that works, together</text></svg>','image/svg+xml')};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a.startsWith('go-'))location.hash=a.slice(3);else actions[a]?.(el)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchDialog()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{const {id,value}=e.target;if(id==='result-search'){filters.q=value;filters.page=0;renderResults()}if(id==='dataset-search'){datasetQuery=value;datasetPage=0;renderDataset()}if(id==='note-search'){noteQuery=value;$('#note-grid').innerHTML=noteCards()}if(id==='task-search'){taskQuery=value;$('#task-list').innerHTML=state.tasks.filter(t=>(taskFilter==='All'||t.status===taskFilter)&&[t.title,t.owner,t.details].join(' ').toLowerCase().includes(value.toLowerCase())).map(taskRow).join('')||empty('No tasks in this view','Try a different search.')}if(id==='task-search')$('#task-count').textContent=state.tasks.filter(t=>(taskFilter==='All'||t.status===taskFilter)&&[t.title,t.owner,t.details].join(' ').toLowerCase().includes(value.toLowerCase())).length+' tasks in this view';if(id==='global-search')searchResults(value)});
document.addEventListener('change',e=>{const {id,value}=e.target;if(id==='result-year'){filters.year=value;filters.office='';filters.page=0;render()}if(id==='result-office'){filters.office=value;filters.page=0;renderResults()}if(id==='dataset-select'){datasetIndex=Number(value);datasetPage=0;datasetQuery='';render()}if(id==='task-filter'){taskFilter=value;render()}if(e.target.dataset.taskCheck){const t=state.tasks.find(r=>r.id===e.target.dataset.taskCheck);if(t){t.status=e.target.checked?'Done':'To do';log((e.target.checked?'Completed: ':'Reopened: ')+t.title);save('Task updated.');render()}}});
document.addEventListener('submit',async e=>{if(e.target.id==='record-form'){e.preventDefault();const type=e.target.dataset.type,id=e.target.dataset.id,record=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(record))record[k]=record[k].trim();if(!record.title){toast('Enter a title.');return}if(type==='ledger')record.amount=Number(record.amount);record.id=id||uid();record.updated=new Date().toISOString();const index=state[type].findIndex(r=>r.id===id);if(index>=0)state[type][index]=record;else state[type].unshift(record);log(`${id?'Updated':'Added'}: ${record.title}`);save('Saved to your workspace.');$('#modal').close();render()}
if(e.target.id==='project-form'){e.preventDefault();const id=e.target.dataset.id;state.projectEdits[id]=Object.fromEntries(new FormData(e.target));log('Updated project annotation');save('Project annotation saved.');$('#modal').close();render()}
if(e.target.id==='feed-form'){e.preventDefault();const url=$('#feed-url').value;if(!url.startsWith('https://')){toast('Use a public HTTPS URL.');return}const button=$('#feed-button');button.disabled=true;button.textContent='Fetching…';try{const response=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('HTTP '+response.status);const len=Number(response.headers.get('content-length'));if(len>5*1024*1024)throw Error('Feed is larger than 5 MB.');const reader=response.body.getReader();let chunks=[],size=0;for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>5*1024*1024){await reader.cancel();throw Error('Feed is larger than 5 MB.')}chunks.push(value)}const text=await new Blob(chunks).text();previewImport(JSON.parse(text),new URL(url).hostname+' feed',url)}catch(error){toast('Could not import feed: '+error.message+'. If access is blocked, download a JSON/CSV file and import it.')}finally{button.disabled=false;button.textContent='Fetch & preview →'}}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>(importMode==='backup'?50:5)*1024*1024)throw Error('File exceeds the import size limit.');const content=await file.text();if(importMode==='backup'){pendingBackup=validateBackup(JSON.parse(content));modal('Restore workspace backup?',`<p>This will replace the current local workspace with <strong>${esc(file.name)}</strong>.</p><p>${pendingBackup.notes.length} notes · ${pendingBackup.tasks.length} tasks · ${pendingBackup.events.length} events · ${pendingBackup.datasets.length} datasets</p><p>Export your current workspace first if you need to preserve it.</p><div class="form-actions">${btn('Export current backup','backup')}${btn('Cancel','close')}${btn('Replace & restore','confirm-restore','accent')}</div>`)}else previewImport(file.name.toLowerCase().endsWith('.csv')?parseCSV(content):JSON.parse(content),file.name)}catch(error){toast('Import stopped: '+error.message)}finally{e.target.value=''}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('storage',e=>{if(e.key===KEY)toast('Another tab changed this workspace. Export your work, then reload to see its changes.')});
function updateClock(){$('#clock').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date())+' ET'}updateClock();setInterval(updateClock,60000);render();
